_leave_settings_cache = {}
_leave_settings_last_refresh = 0
_LEAVE_SETTINGS_REFRESH_SECONDS = 60


def _get_leave_settings(force: bool = False) -> dict:
    """Load all leave_settings rows into a dict (cached, refreshed every 60s)."""
    global _leave_settings_cache, _leave_settings_last_refresh
    now = time.time()
    if not force and (now - _leave_settings_last_refresh) < _LEAVE_SETTINGS_REFRESH_SECONDS:
        return _leave_settings_cache
    try:
        cursor.execute("SELECT key, value FROM leave_settings")
        rows = cursor.fetchall()
        _leave_settings_cache = {r[0]: r[1] for r in rows} if rows else {}
        _leave_settings_last_refresh = now
    except Exception as e:
        print(f"[leave_settings] Error loading: {e}")
    return _leave_settings_cache


def _get_half_day_settings() -> dict:
    """Return half-day config dict with typed values.
    
    half_day_enabled is auto-detected: True if any enabled slot in
    attendance_duration_settings has slot_half = 'first_half' or 'second_half'.
    """
    s = _get_leave_settings()
    default_3m = (datetime.now() + timedelta(days=90)).strftime("%Y-%m-%d")

    # Auto-detect half_day_enabled from slot configuration
    half_day_from_settings = str(s.get("half_day_enabled", "false")).lower() == "true"
    half_day_from_slots = False
    try:
        cursor.execute(
            """
            SELECT COUNT(*) FROM attendance_duration_settings
            WHERE (is_enabled = 1 OR is_enabled::text = 'true') AND slot_half IN ('first_half', 'second_half')
            """
        )
        row = cursor.fetchone()
        half_day_from_slots = (row[0] > 0) if row else False
    except Exception:
        pass

    return {
        "half_day_enabled": half_day_from_settings or half_day_from_slots,
        "first_half_label": s.get("first_half_label", "First Half"),
        "second_half_label": s.get("second_half_label", "Second Half"),
        "cl_monthly_allocation": int(s.get("cl_monthly_allocation", "1") or "1"),
        "cl_expiry_date": s.get("cl_expiry_date") or default_3m,
        "el_expiry_date": s.get("el_expiry_date") or default_3m,
        "auto_expand_checkin_enabled": str(s.get("auto_expand_checkin_enabled", "true")).lower() == "true",
        "auto_expand_checkout_enabled": str(s.get("auto_expand_checkout_enabled", "true")).lower() == "true",
        "auto_expand_fn_minutes": int(s.get("auto_expand_fn_minutes", s.get("auto_expand_minutes", "5")) or "5"),
        "auto_expand_an_minutes": int(s.get("auto_expand_an_minutes", s.get("auto_expand_minutes", "5")) or "5"),
        "auto_expand_minutes": int(s.get("auto_expand_minutes", "5") or "5"),
        "require_fn_check_out": str(s.get("require_fn_check_out", "false")).lower() == "true",
        "first_half_start": s.get("first_half_start", "08:30"),
        "first_half_end": s.get("first_half_end", "13:00"),
        "second_half_start": s.get("second_half_start", "13:00"),
        "second_half_end": s.get("second_half_end", "17:30"),
        "location_tracking_start": s.get("location_tracking_start", "08:30"),
        "location_tracking_end": s.get("location_tracking_end", "17:30"),
    }



def _save_leave_setting(key: str, value: str, updated_by: str = "system"):
    """Upsert a single key in leave_settings and invalidate cache."""
    global _leave_settings_last_refresh
    cursor.execute("SELECT 1 FROM leave_settings WHERE key = %s", (key,))
    if cursor.fetchone():
        cursor.execute(
            "UPDATE leave_settings SET value = %s, updated_at = CURRENT_TIMESTAMP, updated_by = %s WHERE key = %s",
            (value, updated_by, key),
        )
    else:
        cursor.execute(
            "INSERT INTO leave_settings (key, value, updated_by) VALUES (%s, %s, %s)",
            (key, value, updated_by),
        )
    _leave_settings_last_refresh = 0  # invalidate cache


def _compute_daily_status(
    first_half: str | None,
    second_half: str | None,
    target_date: str | None = None,
    current_dt: datetime | None = None,
) -> str:
    """Compute overall daily status from first and second half statuses.

    Rules:
    - Both Present                                → 'Present'
    - One Present + one Pending (window active)   → 'Half Day' (FN/AN Present • pending other)
    - One Present + one Absent (window passed)    → 'Half Day'
    - One Present + one Leave                     → 'Half Day'
    - Both Leave                                  → 'Leave'
    - Both Absent                                 → 'Absent'
    - Both Pending (window active/future date)    → 'Pending'
    """
    if current_dt is None:
        current_dt = datetime.now()

    today_str = current_dt.strftime("%Y-%m-%d")
    hd_settings = _get_half_day_settings()

    # Determine if session windows have passed
    fh_passed = True
    sh_passed = True

    if target_date:
        if target_date > today_str:
            fh_passed = False
            sh_passed = False
        elif target_date == today_str:
            now_time = current_dt.time()
            try:
                fh_end_time = datetime.strptime(
                    hd_settings.get("first_half_end", "13:00"), "%H:%M"
                ).time()
                sh_end_time = datetime.strptime(
                    hd_settings.get("second_half_end", "17:30"), "%H:%M"
                ).time()
                fh_passed = now_time > fh_end_time
                sh_passed = now_time > sh_end_time
            except Exception:
                cutoff = datetime.strptime("13:00", "%H:%M").time()
                fh_passed = now_time > cutoff
                sh_passed = now_time > cutoff

    # Evaluate un-scanned sessions (None or Pending)
    if not first_half or first_half == "Pending":
        fh = "Absent" if fh_passed else "Pending"
    else:
        fh = first_half.strip()

    if not second_half or second_half == "Pending":
        sh = "Absent" if sh_passed else "Pending"
    else:
        sh = second_half.strip()

    pair = (fh, sh)

    if pair == ("Present", "Present"):
        return "Present"
    if pair == ("Present", "Absent") or (fh == "Present" and sh_passed):
        return "Half Day Present (FN)"
    if pair == ("Absent", "Present") or (sh == "Present" and fh_passed):
        return "Half Day Present (AN)"
    if pair == ("Present", "Pending"):
        return "Half Day Present (FN)"
    if pair == ("Pending", "Present"):
        return "Half Day Present (AN)"
    if pair == ("Leave", "Leave"):
        return "Leave"
    if "Leave" in pair:
        return "Leave"
    if pair == ("Absent", "Absent"):
        return "Absent"
    if pair == ("Pending", "Pending"):
        return "Pending"
    if "Pending" in pair:
        return "Pending"

    return "Absent"


def _compute_half_day_value(status: str) -> float:
    """Return numeric day-equivalent for a daily status (for stats)."""
    if status == "Present":
        return 1.0
    if "Half Day" in status or status == "Half Day":
        return 0.5
    if status in ["Leave", "OD"]:
        return 1.0
    return 0.0


def _compute_attendance_value_from_halves(first_half: str | None, second_half: str | None, status: str | None = None, leave_type: str | None = None) -> float:
    """Calculate attendance value (0.0, 0.5, or 1.0) based on half-day statuses and scenario types.
    
    Args:
        first_half: Status of first half ('Present', 'Absent', 'Leave', 'OD', etc.)
        second_half: Status of second half ('Present', 'Absent', 'Leave', 'OD', etc.)
        status: Overall status string
        leave_type: Leave type string
    
    Returns:
        float: Attendance value (1.0 for full day / OD / Holiday, 0.5 for half day, 0.0 for Leave / Absent)
    """
    fh = (first_half or "Absent").strip().lower()
    sh = (second_half or "Absent").strip().lower()
    st = (status or "").strip().lower()
    lt = (leave_type or "").strip().lower()
    
    if st in ["od", "on duty", "on_duty", "permission", "holiday"] or lt in ["od", "on duty", "on_duty"]:
        return 1.0

    value = 0.0
    if fh in ["present", "od", "on duty", "permission"]:
        value += 0.5
    if sh in ["present", "od", "on duty", "permission"]:
        value += 0.5
    
    return value


def _format_scan_status(status_val: str | None, timestamp_val) -> str:
    """Format the scan status to show if it is first half or second half check in/out."""
    if not status_val:
        return "Present"
    
    sv = status_val.lower().strip()
    if sv == "check_out":
        action = "Check-out"
    elif sv == "check_in":
        action = "Check-in"
    else:
        return status_val.replace('_', ' ').title()
    
    try:
        if isinstance(timestamp_val, str):
            ts_norm = timestamp_val[:19].replace("T", " ")
            dt = datetime.strptime(ts_norm, "%Y-%m-%d %H:%M:%S")
        else:
            dt = timestamp_val
        
        if dt.hour < 13:
            return f"First Half {action}"
        else:
            return f"Second Half {action}"
    except Exception:
        return action


def _normalize_attendance_record_halves(log: dict, now_dt: datetime = None) -> dict:
    """Normalize attendance log record so that when timeline is over, pending sessions become Absent permanently."""
    if not isinstance(log, dict):
        return log
    if now_dt is None:
        now_dt = datetime.now()

    today_str = now_dt.strftime("%Y-%m-%d")
    ts = str(log.get("timestamp") or log.get("date") or "")
    rec_date = ts.split("T")[0].split(" ")[0] if ts else ""

    is_past = False
    is_today = False
    if rec_date and len(rec_date) >= 10:
        try:
            if rec_date < today_str:
                is_past = True
            elif rec_date == today_str:
                is_today = True
        except Exception:
            pass

    hd_settings = _get_half_day_settings()
    fn_end_str = hd_settings.get("first_half_end", "13:00")
    an_end_str = hd_settings.get("second_half_end", "17:30")
    
    try:
        fn_h, fn_m = map(int, fn_end_str.split(":"))
        an_h, an_m = map(int, an_end_str.split(":"))
    except Exception:
        fn_h, fn_m = 13, 0
        an_h, an_m = 17, 30

    fn_timeline_over = is_past or (is_today and (now_dt.hour > fn_h or (now_dt.hour == fn_h and now_dt.minute >= fn_m)))
    an_timeline_over = is_past or (is_today and (now_dt.hour > an_h or (now_dt.hour == an_h and now_dt.minute >= an_m)))

    fh = log.get("first_half_status")
    sh = log.get("second_half_status")
    status = str(log.get("status") or "")
    raw_status_lower = status.lower()
    source = str(log.get("source") or "").lower()
    punch_type = str(log.get("punch_type") or log.get("type") or "").lower()
    session = str(log.get("session_type") or log.get("session") or log.get("slot_half") or "").upper()
    val = log.get("attendance_value")

    is_half_raw = (val == 0.5) or "half" in raw_status_lower or session in ["FN", "AN"] or "fn" in raw_status_lower or "an" in raw_status_lower

    has_fn_punch = bool(log.get("first_half_in_time")) or (source == "face_scan" and session in ["FN", "FIRST_HALF", ""]) or (punch_type in ["check_in", "in"] and session != "AN") or (is_half_raw and session != "AN" and not an_timeline_over) or (fh and str(fh).lower() == "present")
    has_an_punch = bool(log.get("second_half_in_time")) or bool(log.get("second_half_out_time")) or (source == "face_scan" and session in ["AN", "SECOND_HALF"]) or (punch_type in ["check_out", "out"] and session != "FN") or (sh and str(sh).lower() == "present")

    is_leave = status in ["Leave", "OD", "On Leave", "On Duty", "On Duty (OD)"] or source in ["leave", "od"] or str(log.get("leave_type") or "").lower() in ["od", "casual", "earned", "medical", "leave"] or "leave" in raw_status_lower or "od" in raw_status_lower

    if is_leave:
        l_type = str(log.get("leave_type") or "").lower()
        is_od = l_type == "od" or "od" in raw_status_lower or source == "od"
        
        # Check if it was a half-day leave or full day
        is_half = (val == 0.5) or "half" in raw_status_lower
        if is_half:
            if "fn" in raw_status_lower or session == "FN":
                fh = "OD" if is_od else "Leave"
                sh = "Present" if has_an_punch else ("Absent" if an_timeline_over else "Pending")
            else:
                fh = "Present" if has_fn_punch else ("Absent" if fn_timeline_over else "Pending")
                sh = "OD" if is_od else "Leave"
            
            att_val = 0.0
            if fh in ["Present", "OD"]:
                att_val += 0.5
            if sh in ["Present", "OD"]:
                att_val += 0.5
            log["first_half_status"] = fh
            log["second_half_status"] = sh
            log["attendance_value"] = att_val
            log["status"] = f"Half Day {'OD' if is_od else 'Leave'} (FN)" if fh in ['OD', 'Leave'] else f"Half Day {'OD' if is_od else 'Leave'} (AN)"
        else:
            fh = "OD" if is_od else "Leave"
            sh = "OD" if is_od else "Leave"
            log["first_half_status"] = fh
            log["second_half_status"] = sh
            log["attendance_value"] = 1.0 if is_od else 0.0
            log["status"] = "On Duty (OD)" if is_od else "On Leave"
        return log

    # Resolve First Half (FN)
    if has_fn_punch or str(fh).lower() == "present":
        fh = "Present"
    elif fh and str(fh).lower() in ["leave", "od"]:
        pass
    else:
        fh = "Absent" if fn_timeline_over else "Pending"

    # Resolve Second Half (AN)
    if has_an_punch or str(sh).lower() == "present":
        sh = "Present"
    elif sh and str(sh).lower() in ["leave", "od"]:
        pass
    else:
        sh = "Absent" if an_timeline_over else "Pending"

    log["first_half_status"] = fh
    log["second_half_status"] = sh

    # Recompute daily status & attendance value
    if fh == "Present" and sh == "Present":
        log["status"] = "Present"
        log["attendance_value"] = 1.0
    elif fh == "Present" and sh == "Absent":
        log["status"] = "Half Day Present (FN)"
        log["attendance_value"] = 0.5
    elif fh == "Absent" and sh == "Present":
        log["status"] = "Half Day Present (AN)"
        log["attendance_value"] = 0.5
    elif fh == "Present" and sh == "Pending":
        log["status"] = "Half Day Present (FN)"
        log["attendance_value"] = 0.5
    elif fh == "Pending" and sh == "Present":
        log["status"] = "Half Day Present (AN)"
        log["attendance_value"] = 0.5
    elif fh == "Pending" and sh == "Pending":
        log["status"] = "Pending"
        log["attendance_value"] = 0.0
    elif (fh == "Absent" and sh == "Pending") or (fh == "Pending" and sh == "Absent"):
        log["status"] = "Pending"
        log["attendance_value"] = 0.0
    else: # Absent and Absent
        log["status"] = "Absent"
        log["attendance_value"] = 0.0

    return log


def _sync_overdue_pending_absences():
    """Permanent database synchronization: Reassign pending/NULL sessions to Absent when timeline is over."""
    try:
        now = datetime.now()
        today_str = now.strftime("%Y-%m-%d")
        hd = _get_half_day_settings()
        fn_end = hd.get("first_half_end", "13:00")
        an_end = hd.get("second_half_end", "17:30")
        time_str = now.strftime("%H:%M")

        # 1. Past dates: all NULL or 'Pending' halves must be 'Absent'
        cursor.execute("""
            SELECT reg_no, date, first_half_status, second_half_status, status, leave_type
            FROM daily_attendance_status
            WHERE date < %s AND (
                first_half_status IS NULL OR first_half_status = 'Pending' OR
                second_half_status IS NULL OR second_half_status = 'Pending' OR
                status = 'Pending'
            )
        """, (today_str,))
        past_rows = cursor.fetchall()
        for r in past_rows:
            reg_no, d_str, fh, sh, st, lt = r
            if st in ["Leave", "OD"] or (lt and str(lt).lower() in ["od", "casual", "earned", "medical", "leave"]):
                continue
            new_fh = "Present" if fh == "Present" else "Absent"
            new_sh = "Present" if sh == "Present" else "Absent"
            new_status = _compute_daily_status(new_fh, new_sh, target_date=str(d_str), current_dt=now)
            val = _compute_attendance_value_from_halves(new_fh, new_sh)
            cursor.execute("""
                UPDATE daily_attendance_status
                SET first_half_status = %s,
                    second_half_status = %s,
                    status = %s,
                    attendance_value = %s,
                    marked_at = CURRENT_TIMESTAMP
                WHERE reg_no = %s AND date = %s
            """, (new_fh, new_sh, new_status, val, reg_no, d_str))

        # 2. Today: if FN window closed (time >= fn_end), resolve FN
        if time_str >= fn_end:
            cursor.execute("""
                SELECT reg_no, first_half_status, second_half_status, status, leave_type
                FROM daily_attendance_status
                WHERE date = %s AND (first_half_status IS NULL OR first_half_status = 'Pending')
            """, (today_str,))
            today_fn_rows = cursor.fetchall()
            for r in today_fn_rows:
                reg_no, fh, sh, st, lt = r
                if st in ["Leave", "OD"] or (lt and str(lt).lower() in ["od", "casual", "earned", "medical", "leave"]):
                    continue
                new_fh = "Absent"
                new_sh = sh
                new_status = _compute_daily_status(new_fh, new_sh, target_date=today_str, current_dt=now)
                val = _compute_attendance_value_from_halves(new_fh, new_sh)
                cursor.execute("""
                    UPDATE daily_attendance_status
                    SET first_half_status = %s,
                        status = %s,
                        attendance_value = %s,
                        marked_at = CURRENT_TIMESTAMP
                    WHERE reg_no = %s AND date = %s
                """, (new_fh, new_status, val, reg_no, today_str))

        # 3. Today: if AN window closed (time >= an_end), resolve AN
        if time_str >= an_end:
            cursor.execute("""
                SELECT reg_no, first_half_status, second_half_status, status, leave_type
                FROM daily_attendance_status
                WHERE date = %s AND (second_half_status IS NULL OR second_half_status = 'Pending')
            """, (today_str,))
            today_an_rows = cursor.fetchall()
            for r in today_an_rows:
                reg_no, fh, sh, st, lt = r
                if st in ["Leave", "OD"] or (lt and str(lt).lower() in ["od", "casual", "earned", "medical", "leave"]):
                    continue
                new_fh = fh
                new_sh = "Absent"
                new_status = _compute_daily_status(new_fh, new_sh, target_date=today_str, current_dt=now)
                val = _compute_attendance_value_from_halves(new_fh, new_sh)
                cursor.execute("""
                    UPDATE daily_attendance_status
                    SET first_half_status = %s,
                        second_half_status = %s,
                        status = %s,
                        attendance_value = %s,
                        marked_at = CURRENT_TIMESTAMP
                    WHERE reg_no = %s AND date = %s
                """, (new_fh, new_sh, new_status, val, reg_no, today_str))

        conn.commit()
    except Exception as e:
        print(f"[SYNC_OVERDUE_ABSENCES] Error: {e}")


def _process_session_absences(date_str: str, session: str):
    """Mark users (Staff, HOD, Other Staff) as absent for a specific session (FN or AN) if they haven't marked attendance."""
    try:
        now = datetime.now()
        target_roles = ('staff', 'hod') + OTHER_STAFF_ROLES
        placeholders = ','.join(['%s'] * len(target_roles))

        condition = "first_half_status IS NULL" if session == "FN" else "second_half_status IS NULL"

        cursor.execute(f"""
            SELECT reg_no, name, dept, first_half_status, second_half_status
            FROM daily_attendance_status
            WHERE date = %s AND {condition}
        """, (date_str,))
        
        rows = cursor.fetchall()
        updated = 0
        for row in rows:
            reg_no, name, dept, fh, sh = row
            
            if session == "FN":
                new_fh = fh if fh else "Absent"
                new_sh = sh
            else:  # AN
                new_fh = fh
                new_sh = sh if sh else "Absent"
                
            new_status = _compute_daily_status(new_fh, new_sh, target_date=date_str, current_dt=now)
            attendance_value = _compute_attendance_value_from_halves(new_fh, new_sh)
            
            cursor.execute("""
                UPDATE daily_attendance_status
                SET first_half_status = %s,
                    second_half_status = %s,
                    status = %s,
                    attendance_value = %s,
                    marked_at = CURRENT_TIMESTAMP
                WHERE reg_no = %s AND date = %s
            """, (new_fh, new_sh, new_status, attendance_value, reg_no, date_str))
            updated += 1
            
        # Also mark regular users (staff, HOD) with NO record at all
        cursor.execute(f"""
            SELECT u.reg_no, u.name, u.dept
            FROM users u
            WHERE NOT EXISTS (
                SELECT 1 FROM daily_attendance_status das
                WHERE das.reg_no = u.reg_no AND das.date = %s
            )
              AND u.role IN ({placeholders})
        """, [date_str] + list(target_roles))
        
        missing = cursor.fetchall()
        for reg_no, name, dept in missing:
            if session == "FN":
                cursor.execute("""
                    INSERT INTO daily_attendance_status
                      (reg_no, name, dept, date, status, first_half_status, second_half_status, attendance_value, marked_by, marked_at)
                    VALUES (%s, %s, %s, %s, 'Pending', 'Absent', NULL, 0.0, 'System Auto', CURRENT_TIMESTAMP)
                    ON CONFLICT (reg_no, date) DO NOTHING
                """, (reg_no, name, dept, date_str))
            else: # AN
                cursor.execute("""
                    INSERT INTO daily_attendance_status
                      (reg_no, name, dept, date, status, first_half_status, second_half_status, attendance_value, marked_by, marked_at)
                    VALUES (%s, %s, %s, %s, 'Absent', 'Absent', 'Absent', 0.0, 'System Auto', CURRENT_TIMESTAMP)
                    ON CONFLICT (reg_no, date) DO NOTHING
                """, (reg_no, name, dept, date_str))
            updated += 1

        # Also mark other_staff with NO record at all
        cursor.execute("""
            SELECT os.reg_no, os.name, os.dept
            FROM other_staff os
            WHERE NOT EXISTS (
                SELECT 1 FROM daily_attendance_status das
                WHERE das.reg_no = os.reg_no AND das.date = %s
            )
        """, (date_str,))
        missing_os = cursor.fetchall()
        for reg_no, name, dept in missing_os:
            if session == "FN":
                cursor.execute("""
                    INSERT INTO daily_attendance_status
                      (reg_no, name, dept, date, status, first_half_status, second_half_status, attendance_value, marked_by, marked_at)
                    VALUES (%s, %s, %s, %s, 'Pending', 'Absent', NULL, 0.0, 'System Auto', CURRENT_TIMESTAMP)
                    ON CONFLICT (reg_no, date) DO NOTHING
                """, (reg_no, name, dept, date_str))
            else: # AN
                cursor.execute("""
                    INSERT INTO daily_attendance_status
                      (reg_no, name, dept, date, status, first_half_status, second_half_status, attendance_value, marked_by, marked_at)
                    VALUES (%s, %s, %s, %s, 'Absent', 'Absent', 'Absent', 0.0, 'System Auto', CURRENT_TIMESTAMP)
                    ON CONFLICT (reg_no, date) DO NOTHING
                """, (reg_no, name, dept, date_str))
            updated += 1

        conn.commit()
        print(f"[{session}] Auto absence marking done for {date_str}: {updated} records updated.")
    except Exception as e:
        print(f"[{session}] Error in _process_session_absences({date_str}): {e}")



def _mark_halves_absent_for_day(date_str: str):
    """End-of-day job: for every user, set NULL halves to 'Absent' and recompute status.

    Should be called after the second-half window closes for that date.
    Only runs when half_day_enabled = True.
    """
    _process_session_absences(date_str, "AN")


def _check_and_expire_leaves(triggered_by: str = "system"):
    """Check CL/EL expiry dates; zero out balances if today >= expiry date."""
    hd = _get_leave_settings(force=True)
    today_str = datetime.now().strftime("%Y-%m-%d")
    results = {"cl_expired": 0, "el_expired": 0}

    # CL expiry
    cl_expiry = hd.get("cl_expiry_date") or ""
    if cl_expiry and today_str >= cl_expiry:
        try:
            cursor.execute(
                """
                UPDATE casual_leave
                SET current_month_cl_available = 0,
                    accumulated_cl = 0,
                    last_updated = CURRENT_TIMESTAMP
                WHERE current_month_cl_available > 0 OR accumulated_cl > 0
            """
            )
            results["cl_expired"] = cursor.rowcount or 0
            conn.commit()
            log_audit_event("CL_EXPIRED", triggered_by, True, f"CL expired on {today_str} (expiry: {cl_expiry})")
            print(f"[Leave Expiry] CL expired for {results['cl_expired']} records.")
        except Exception as e:
            print(f"[Leave Expiry] CL expiry error: {e}")

    # EL expiry
    el_expiry = hd.get("el_expiry_date") or ""
    if el_expiry and today_str >= el_expiry:
        try:
            cursor.execute(
                """
                UPDATE earned_leave
                SET balance = 0.0,
                    updated_at = CURRENT_TIMESTAMP
                WHERE balance > 0
            """
            )
            results["el_expired"] = cursor.rowcount or 0
            conn.commit()
            log_audit_event("EL_EXPIRED", triggered_by, True, f"EL expired on {today_str} (expiry: {el_expiry})")
            print(f"[Leave Expiry] EL expired for {results['el_expired']} records.")
        except Exception as e:
            print(f"[Leave Expiry] EL expiry error: {e}")

    return results


def _init_db_schema():
    """Initialize database schema with multi-worker safety.

    Uses PostgreSQL advisory lock so only one worker runs DDL.
    Other workers skip since tables/indexes use IF NOT EXISTS.
    """

    lock_acquired = False
    try:
        cursor.execute("SELECT pg_try_advisory_lock(123456789)")
        res = cursor.fetchone()
        lock_acquired = res[0] if res else False
    except Exception as e:
        print(f"Notice: Database connection for DDL init not immediately ready during module load ({e}). Migrations runner will initialize tables.")
        return

    if not lock_acquired:
        print("Schema init skipped (another worker is handling it)")
        return

    try:
        _run_ddl()
    except Exception as e:
        if "tuple concurrently updated" in str(e):
            print(f"DDL concurrency conflict (non-critical): {e}")
        else:
            print(f"Notice: Schema DDL execution notice: {e}")
    finally:
        try:
            cursor.execute("SELECT pg_advisory_unlock(123456789)")
        except Exception:
            pass


