def verify_hod_token(request: Request) -> dict:
    """Verify HOD authentication token"""
    auth_header = request.headers.get("Authorization")
    if not auth_header or not auth_header.startswith("Bearer "):
        raise HTTPException(
            status_code=401, detail="Missing or invalid authorization header"
        )

    token = auth_header.replace("Bearer ", "")

    try:
        import base64

        decoded = base64.b64decode(token).decode("utf-8")
        parts = decoded.split(":")
        if len(parts) < 2:
            raise HTTPException(status_code=401, detail="Invalid credentials format")
        username, password = parts[0], parts[1]

        user = get_user_by_username(username)
        if not user:
            raise HTTPException(status_code=401, detail="Invalid credentials")

        if not verify_password(password, user[2]):
            raise HTTPException(status_code=401, detail="Invalid credentials")

        # Check if user is suspended
        if is_user_suspended(username, is_other_staff=False):
            raise HTTPException(status_code=403, detail="Account suspended. Access denied.")

        # Check if user is HOD or Admin
        if user[6] not in ["hod", "admin"]:
            raise HTTPException(status_code=403, detail="HOD access required")

        return {
            "id": user[0],
            "username": user[1],
            "reg_no": user[3],
            "name": user[4],
            "dept": user[5],
            "role": user[6],
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=401, detail="Invalid token")


@app.post("/hod/login")
async def hod_login(request: Request):
    """HOD login endpoint"""
    try:
        data = await request.json()
        username = data.get("username")
        password = data.get("password")

        if not username or not password:
            raise HTTPException(status_code=400, detail="Missing credentials")

        user = get_user_by_username(username)
        if not user:
            raise HTTPException(status_code=401, detail="Invalid credentials")

        if not verify_password(password, user[2]):
            raise HTTPException(status_code=401, detail="Invalid credentials")

        # Check role
        if user[6] != "hod":
            raise HTTPException(status_code=403, detail="HOD access required")

        # Create token
        import base64

        token = base64.b64encode(f"{username}:{password}".encode("utf-8")).decode(
            "utf-8"
        )

        user_dept = user[5]
        print(
            f"[HOD_LOGIN] HOD '{user[4]}' (username: {username}) logging in with department: {user_dept}"
        )

        return {
            "message": "HOD login successful",
            "token": token,
            "user": {
                "id": user[0],
                "username": user[1],
                "regNo": user[3],
                "name": user[4],
                "dept": user[5],
                "role": user[6],
            },
        }
    except HTTPException:
        raise
    except Exception as e:
        print(f"HOD login error: {e}")
        raise HTTPException(status_code=500, detail="Login failed")


@app.get("/hod/dashboard")
async def hod_dashboard(request: Request):
    """Get HOD dashboard statistics (department-specific)"""
    try:
        hod_user = verify_hod_token(request)
        dept = hod_user["dept"]

        # Get counts for this department only
        cursor.execute("SELECT COUNT(*) FROM attendance WHERE dept = %s", (dept,))
        row = cursor.fetchone()
        dept_attendance = row[0] if row else 0

        cursor.execute(
            "SELECT COUNT(*) FROM attendance WHERE dept = %s AND timestamp::date = CURRENT_DATE",
            (dept,),
        )
        row = cursor.fetchone()
        today_attendance = row[0] if row else 0

        cursor.execute(
            "SELECT COUNT(*) FROM users WHERE dept = %s AND role = 'staff'", (dept,)
        )
        row = cursor.fetchone()
        dept_staff = row[0] if row else 0

        # Get recent attendance for this department (face scan + OD)
        cursor.execute(
            """
            SELECT id, reg_no, name, dept, class_div, timestamp, 'face_scan' as source, status
            FROM attendance 
            WHERE dept = %s 
            ORDER BY id DESC 
            LIMIT 8
        """,
            (dept,),
        )
        face_scan_attendance = cursor.fetchall() or []

        # Get OD records for today with approval date
        cursor.execute(
            """
            SELECT das.id, das.reg_no, das.name, das.dept, das.date as timestamp, 'od' as source, 
                   das.leave_type, lr.processed_date
            FROM daily_attendance_status das
            LEFT JOIN leave_requests lr ON das.leave_request_id = lr.id
            WHERE das.dept = %s AND das.date::date = CURRENT_DATE AND das.status = 'Present' 
            AND das.leave_type IN ('od', 'earned', 'casual')
            ORDER BY das.date DESC
            LIMIT 5
        """,
            (dept,),
        )
        od_records = cursor.fetchall() or []

        # Combine face scan + OD
        combined = list(face_scan_attendance) + list(od_records)
        combined.sort(key=lambda x: str(x[5]) if len(x) > 5 and x[5] else "", reverse=True)
        recent_attendance = combined[:10]

        # Get today's OD count for department (separate counts)
        cursor.execute(
            """
            SELECT leave_type, COUNT(*) as cnt
            FROM daily_attendance_status
            WHERE dept = %s AND date::date = CURRENT_DATE AND status = 'Present' 
            AND leave_type IN ('od', 'earned', 'casual')
            GROUP BY leave_type
        """,
            (dept,),
        )
        od_breakdown = cursor.fetchall() or []
        od_count = sum(row[1] for row in od_breakdown)
        earned_count = sum(row[1] for row in od_breakdown if row[0] == "earned")
        casual_count = sum(row[1] for row in od_breakdown if row[0] == "casual")

        # Build recent_attendance list with approval_date
        recent_attendance_list = []
        for row in recent_attendance:
            is_od = len(row) > 5 and row[5] == "od"
            if is_od:
                # OD record with approval date
                recent_attendance_list.append(
                    {
                        "id": row[0],
                        "reg_no": row[1],
                        "name": row[2],
                        "dept": row[3],
                        "timestamp": str(row[4]) if row[4] else "",
                        "source": "od",
                        "leave_type": row[6] if len(row) > 6 else "od",
                        "approval_date": _ts(row[7]) if len(row) > 7 and row[7] else None,
                    }
                )
            else:
                # Face scan record
                raw_status = row[7] if len(row) > 7 else None
                recent_attendance_list.append(
                    {
                        "id": row[0],
                        "reg_no": row[1],
                        "name": row[2],
                        "dept": row[3],
                        "class_div": row[4] or "",
                        "timestamp": _ts(row[5])
                        if len(row) > 5 and row[5]
                        else str(row[5])
                        if len(row) > 5
                        else "",
                        "source": "face_scan",
                        "leave_type": None,
                        "status": _format_scan_status(raw_status, row[5] if len(row) > 5 else None),
                        "punch_type": raw_status or "check_in",
                    }
                )

        # Calculate present and absent for department
        total_staff_in_dept = dept_staff
        today_present_count = today_attendance + od_count
        today_absent_count = max(0, total_staff_in_dept - today_present_count)

        # --- Pie chart: breakdown from daily_attendance_status for dept ---
        cursor.execute(
            """
            SELECT status, COUNT(*) as cnt
            FROM daily_attendance_status
            WHERE dept = %s AND date::date = CURRENT_DATE
            GROUP BY status
        """,
            (dept,),
        )
        das_breakdown = {row[0]: row[1] for row in cursor.fetchall() or []}
        pie_full_day  = das_breakdown.get("Present", 0)
        pie_half_day  = das_breakdown.get("Half Day", 0)
        pie_absent    = das_breakdown.get("Absent", 0)
        pie_leave     = das_breakdown.get("Leave", 0)
        pie_holiday   = das_breakdown.get("Holiday", 0)

        return JSONResponse(
            content={
                "stats": {
                    "department": dept,
                    "total_attendance": dept_attendance,
                    "today_attendance": today_attendance + od_count,
                    "today_face_scan": today_attendance,
                    "today_od": od_count,
                    "today_earned": earned_count,
                    "today_casual": casual_count,
                    "total_staff": dept_staff,
                    "today_present": today_present_count,
                    "today_absent": today_absent_count,
                    # Pie chart breakdown fields
                    "today_full_day": pie_full_day,
                    "today_half_day": pie_half_day,
                    "today_leave": pie_leave,
                    "today_holiday": pie_holiday,
                },
                "recent_attendance": recent_attendance_list,
                "hod_user": hod_user,
            },
            headers={
                "Cache-Control": "no-cache, no-store, must-revalidate, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
            },
        )
    except HTTPException:
        raise
    except Exception as e:
        print(f"Error in hod_dashboard: {e}")
        import traceback
        traceback.print_exc()
        return JSONResponse(
            status_code=500,
            content={"detail": f"HOD dashboard error: {str(e)}"},
        )


@app.get("/hod/recent-attendance")
async def hod_recent_attendance(request: Request, dept: str = None):
    """Get recent attendance records for auto-refresh in HOD panel"""
    try:
        user_dept = dept
        try:
            hod_user = verify_hod_token(request)
            if hod_user and hod_user.get("dept"):
                user_dept = hod_user["dept"]
        except Exception:
            pass
        if not user_dept:
            user_dept = "CSE"

        # Face scan attendance
        cursor.execute(
            """
            SELECT id, reg_no, name, dept, class_div, timestamp, 'face_scan' as source, status
            FROM attendance 
            WHERE dept = %s 
            ORDER BY id DESC 
            LIMIT 10
        """,
            (user_dept,),
        )
        face_scan_attendance = cursor.fetchall() or []

        # OD/Leave records for today
        cursor.execute(
            """
            SELECT das.id, das.reg_no, das.name, das.dept, das.date as timestamp, 
                   (CASE WHEN das.status = 'Absent' THEN 'absent_record' ELSE 'od' END) as source, 
                   das.leave_type, lr.processed_date, das.status, das.absent_reason
            FROM daily_attendance_status das
            LEFT JOIN leave_requests lr ON das.leave_request_id = lr.id
            WHERE das.dept = %s AND das.date::date = CURRENT_DATE 
            AND (
                (das.status = 'Present' AND das.leave_type IN ('od', 'earned', 'casual'))
                OR (das.status = 'Absent')
            )
            ORDER BY das.date DESC
            LIMIT 10
        """,
            (user_dept,),
        )
        status_records = cursor.fetchall() or []

        combined = list(face_scan_attendance) + list(status_records)
        combined.sort(
            key=lambda x: str(x[5]) if len(x) > 5 and x[5] else (str(x[4]) if len(x) > 4 and x[4] else ""),
            reverse=True,
        )
        recent_attendance = combined[:10]

        # Counts
        cursor.execute(
            "SELECT COUNT(*) FROM attendance WHERE dept = %s AND timestamp::date = CURRENT_DATE",
            (user_dept,),
        )
        row = cursor.fetchone()
        today_attendance = row[0] if row else 0

        cursor.execute(
            """
            SELECT leave_type, COUNT(*) as cnt
            FROM daily_attendance_status
            WHERE dept = %s AND date::date = CURRENT_DATE AND status = 'Present' AND leave_type IN ('od', 'earned', 'casual')
            GROUP BY leave_type
        """,
            (user_dept,),
        )
        od_breakdown = cursor.fetchall() or []
        od_count = sum(r[1] for r in od_breakdown)
        earned_count = sum(r[1] for r in od_breakdown if r[0] == "earned")
        casual_count = sum(r[1] for r in od_breakdown if r[0] == "casual")

        recent_attendance_list = []
        for row in recent_attendance:
            if len(row) > 6 and row[6] == "face_scan":
                raw_status = row[7] if len(row) > 7 else None
                recent_attendance_list.append(
                    {
                        "id": row[0],
                        "reg_no": row[1],
                        "name": row[2],
                        "dept": row[3],
                        "class_div": row[4] or "",
                        "timestamp": _ts(row[5]) if len(row) > 5 and row[5] else "",
                        "source": "face_scan",
                        "leave_type": None,
                        "status": _format_scan_status(raw_status, row[5] if len(row) > 5 else None),
                        "punch_type": raw_status or "check_in",
                    }
                )
            else:
                recent_attendance_list.append(
                    {
                        "id": row[0],
                        "reg_no": row[1],
                        "name": row[2],
                        "dept": row[3],
                        "timestamp": str(row[4]) if row[4] else "",
                        "source": row[5] if len(row) > 5 else "od",
                        "leave_type": row[6] if len(row) > 6 else None,
                        "approval_date": _ts(row[7]) if len(row) > 7 and row[7] else None,
                        "status": row[8] if len(row) > 8 else "Present",
                        "absent_reason": row[9] if len(row) > 9 else None,
                    }
                )

        return {
            "stats": {
                "today_attendance": today_attendance + od_count,
                "today_face_scan": today_attendance,
                "today_od": od_count,
                "today_earned": earned_count,
                "today_casual": casual_count,
            },
            "recent_attendance": recent_attendance_list,
        }
    except Exception as e:
        print(f"Error in hod_recent_attendance: {e}")
        return {"stats": {}, "recent_attendance": []}


@app.get("/hod/attendance")
async def hod_get_attendance(request: Request, date: str = None):
    """Get attendance records for HOD's department only"""
    hod_user = verify_hod_token(request)
    dept = hod_user["dept"]

    try:
        # Use explicit column names to avoid IndexError
        if date:
            cursor.execute(
                """
                SELECT id, reg_no, name, dept, class_div, timestamp, status
                FROM attendance 
                WHERE dept = %s AND timestamp::date = %s 
                ORDER BY id DESC
            """,
                (dept, date),
            )
        else:
            cursor.execute(
                """
                SELECT id, reg_no, name, dept, class_div, timestamp, status
                FROM attendance 
                WHERE dept = %s 
                ORDER BY id DESC
            """,
                (dept,),
            )

        rows = cursor.fetchall()
        return {
            "attendance": [
                {
                    "id": row[0],
                    "reg_no": row[1],
                    "name": row[2],
                    "dept": row[3],
                    "class_div": row[4] or "",
                    "timestamp": _ts(row[5]),
                    "status": _format_scan_status(row[6], row[5]),
                }
                for row in rows
            ],
            "count": len(rows),
        }
    except Exception as e:
        print(f"Error fetching attendance: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch attendance")


@app.get("/hod/attendance/staff")
async def hod_get_staff_attendance(request: Request, date: str = None):
    """Get staff attendance records for HOD's department only"""
    hod_user = verify_hod_token(request)
    dept = hod_user["dept"]

    try:
        # Get all attendance for department, then filter by role from users table in memory
        if date:
            cursor.execute(
                """
                SELECT a.id, a.reg_no, a.name, a.dept, a.timestamp, a.status 
                FROM attendance a
                WHERE a.dept = %s AND a.timestamp::date = %s
                ORDER BY a.id DESC
            """,
                (dept, date),
            )
        else:
            cursor.execute(
                """
                SELECT a.id, a.reg_no, a.name, a.dept, a.timestamp, a.status 
                FROM attendance a
                WHERE a.dept = %s
                ORDER BY a.id DESC
            """,
                (dept,),
            )

        attendance_rows = cursor.fetchall()

        # Get all users in this department with their roles
        cursor.execute("SELECT reg_no, role FROM users WHERE dept = %s", (dept,))
        user_rows = cursor.fetchall()
        user_roles = {row[0]: row[1] for row in user_rows}

        # Filter to only staff and hod attendance
        filtered_attendance = []
        for row in attendance_rows:
            reg_no = row[1]
            if user_roles.get(reg_no) in ["staff", "hod"]:
                filtered_attendance.append(
                    {
                        "id": row[0],
                        "reg_no": row[1],
                        "name": row[2],
                        "dept": row[3],
                        "timestamp": _ts(row[4]),
                        "status": _format_scan_status(row[5], row[4]),
                        "role": user_roles.get(reg_no),
                    }
                )

        return {"attendance": filtered_attendance, "count": len(filtered_attendance)}
    except Exception as e:
        print(f"Error fetching staff attendance: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch staff attendance")


@app.get("/hod/staff")
async def hod_get_staff(request: Request):
    """Get staff members in HOD's department with face status"""
    hod_user = verify_hod_token(request)
    dept = hod_user["dept"]
    is_admin = hod_user.get("role") == "admin"

    try:
        if is_admin and not dept:
            cursor.execute(
                """
                SELECT id, username, reg_no, name, dept, role, created_at, embedding, can_reregister, COALESCE(suspended, FALSE)
                FROM users
                WHERE role = 'staff'
                ORDER BY name ASC
                """
            )
        else:
            cursor.execute(
                """
                SELECT id, username, reg_no, name, dept, role, created_at, embedding, can_reregister, COALESCE(suspended, FALSE)
                FROM users
                WHERE TRIM(LOWER(dept)) = TRIM(LOWER(?)) AND role = 'staff'
                ORDER BY name ASC
                """,
                (dept,),
            )
        rows = cursor.fetchall()

        staff_list = []
        for row in rows:
            if isinstance(row, dict):
                r_id = row.get("id")
                r_uname = row.get("username")
                r_reg = row.get("reg_no")
                r_name = row.get("name")
                r_dept = row.get("dept")
                r_role = row.get("role")
                r_created = row.get("created_at")
                r_emb = row.get("embedding")
                r_can = row.get("can_reregister")
                r_susp = row.get("suspended")
            else:
                r_id, r_uname, r_reg, r_name, r_dept, r_role, r_created, r_emb, r_can = row[0:9]
                r_susp = row[9] if len(row) > 9 else False

            has_face = r_emb is not None
            if not has_face and r_reg:
                try:
                    cursor.execute("SELECT COUNT(*) FROM face_embedding_samples WHERE reg_no = ?", (r_reg,))
                    cnt = cursor.fetchone()
                    if cnt and cnt[0] > 0:
                        has_face = True
                except Exception:
                    pass

            staff_list.append({
                "id": r_id,
                "username": r_uname,
                "reg_no": r_reg,
                "name": r_name,
                "dept": r_dept,
                "role": r_role,
                "created_at": r_created,
                "face_registered": bool(has_face),
                "can_reregister": bool(r_can),
                "suspended": bool(r_susp),
            })

        return {
            "staff": staff_list,
            "count": len(staff_list),
            "filter_applied": f"dept={dept}",
        }
    except Exception as e:
        print(f"Error fetching staff: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch staff")


